using CommunityToolkit.Mvvm.ComponentModel; using CommunityToolkit.Mvvm.Input; using DarouichTravaux.Application; using DarouichTravaux.Maui.Services;
namespace DarouichTravaux.Maui.ViewModels; public partial class SettingsViewModel(IBackupService backups,IAuthenticationService authentication,INavigationService navigation):ObservableObject { [ObservableProperty]private string status="";[ObservableProperty]private string currentPassword="";[ObservableProperty]private string newPassword="";[ObservableProperty]private string confirmation="";[RelayCommand]private async Task BackupAsync(){try{Status=$"Sauvegarde créée : {await backups.CreateBackupAsync()}";}catch(Exception ex){Status=ex.Message;}}[RelayCommand]private async Task RestoreAsync(){var result=await FilePicker.Default.PickAsync(new PickOptions{PickerTitle="Choisir une sauvegarde SQLite"});if(result is null)return;try{await backups.RestoreBackupAsync(result.FullPath);Status="Sauvegarde restaurée. Redémarrez l’application.";}catch(Exception ex){Status=ex.Message;}}[RelayCommand]private async Task OpenBackupFolderAsync()=>await Launcher.Default.OpenAsync(new Uri(backups.BackupDirectory));[RelayCommand]private async Task ChangePasswordAsync(){if(NewPassword!=Confirmation){Status="Les mots de passe ne correspondent pas.";return;}try{await authentication.ChangePasswordAsync(CurrentPassword,NewPassword);CurrentPassword=NewPassword=Confirmation="";Status="Votre mot de passe a été modifié avec succès.";}catch(Exception ex){Status=ex.Message;}}[RelayCommand]private void Logout(){authentication.Logout();navigation.ShowLogin();} }
